WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY budget, id) AS dedup_rank FROM departments) ranked WHERE dedup_rank = 1) SELECT CASE WHEN budget >= 3637000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, ROUND(AVG(budget), 2) AS avg_budget, COUNT(*) AS num_rows FROM ranked GROUP BY CASE WHEN budget >= 3637000 THEN 'LARGE' ELSE 'SMALL' END ORDER BY avg_budget DESC NULLS FIRST;
